import csv,json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
BUILD=ROOT/'runs/dev-adapted-text-v1/results/enterprise-expanded20-agentrunbook-r-officialroot-build-v1'
READER=ROOT/'runs/dev-adapted-text-v1/results/enterprise-expanded20-agentrunbook-r-officialroot-reader-matched-v2'
OUT=ROOT/'results/tables/paper03_expanded20_agentrunbook_r.csv'
REPORT=ROOT/'reports/paper03_expanded20_agentrunbook_r.md'
def rows(p): return [json.loads(x) for x in p.open() if x.strip()]
def main():
    summary=json.loads((BUILD/'memory_build_summary.json').read_text()); calls=rows(BUILD/'memory_state/model_calls.jsonl'); agg=json.loads((READER/'aggregated_metrics.json').read_text()); rr=rows(READER/'per_question.jsonl')
    # Reader calls are appended to the persisted snapshot's shared call log.
    # Keep the cold-build row construction-only rather than counting those.
    build_calls=[r for r in calls if r.get('query_invocation_id') is None]
    ctl=[r for r in build_calls if r.get('channel')=='controller']; emb=[r for r in build_calls if r.get('channel')=='embedding']
    def total(ch,k): return sum((r.get(k) or 0) for r in build_calls if r.get('channel')==ch)
    row={'method':'AgentRunbook-R','scope':'expanded20 enterprise / 10 complete trajectories / 152 raw states / 142 events / 4 fixed questions','input_modality':'text-only/adapted','build_wall_s':summary['elapsed_seconds'],'build_wall_external_s':float((BUILD/'wall_time.txt').read_text().split('=')[-1]),'trajectory_count':summary['trajectory_count'],'raw_state_count':152,'event_count':142,'build_controller_calls':len(ctl),'build_controller_input_tokens':total('controller','prompt_tokens'),'build_controller_output_tokens':total('controller','completion_tokens'),'build_embedding_calls':len(emb),'build_embedding_input_tokens':total('embedding','prompt_tokens'),'build_embedding_vectors':sum(r.get('input_text_count') or 0 for r in emb),'joint_event_groups':sum(r.get('channel')=='event_group' for r in build_calls),'bounded_fallbacks':sum(r.get('status')=='bounded_existing_fallback' for r in build_calls),'build_failures':sum(r.get('status') in {'failed','error'} for r in build_calls),'reader_prompt_build_s':agg['timing']['prompt_build_wall_seconds'],'reader_generation_s':agg['timing']['reader_generation_wall_seconds'],'reader_calls':len(rr),'reader_input_tokens':agg['tokens']['prompt_tokens'],'reader_output_tokens':agg['tokens']['completion_tokens'],'complete_parseable':agg['answer_status']['complete_parseable'],'correct':agg['answer_status']['correct'],'pending':agg['answer_status']['pending_judge'],'truncated':agg['answer_status']['truncated'],'service_failure':agg['answer_status']['service_failure'],'parse_failure':agg['answer_status']['parse_failure'],'accuracy_all_questions':agg['overall']['overall_full_set'],'quality_scope':'deterministic phrase matching on 4 fixed enterprise questions; adapted, not official Judge','build_run':str(BUILD.relative_to(ROOT)),'reader_run':str(READER.relative_to(ROOT)),'configuration':'event_group_size=2; event_output_tokens=1024; event_max_input_tokens=18000; exact build-embedding reuse; query chunking/tokenizer cache/lexical backfill; reader context=12000/output=2048/thinking=off'}
    OUT.parent.mkdir(parents=True,exist_ok=True)
    with OUT.open('w',newline='') as f: w=csv.DictWriter(f,fieldnames=list(row)); w.writeheader(); w.writerow(row)
    REPORT.parent.mkdir(parents=True,exist_ok=True)
    REPORT.write_text('# PAPER03 expanded20 adapted AgentRunbook-R\n\n'+f"Cold build to persisted/reload-verified publish: **{row['build_wall_external_s']:.2f}s** for 10 trajectories (152 raw states, 142 events, 10 procedure and 10 hint notes).\n\nController: **{row['build_controller_calls']}** calls, **{row['build_controller_input_tokens']:,}** input and **{row['build_controller_output_tokens']:,}** output tokens; failures **{row['build_failures']}**. Embedding: **{row['build_embedding_calls']}** requests, **{row['build_embedding_vectors']}** input texts and **{row['build_embedding_input_tokens']:,}** tokens. Joint groups **{row['joint_event_groups']}**, bounded fallbacks **{row['bounded_fallbacks']}**.\n\nMatched Reader: **{row['complete_parseable']}/4** complete/parseable, **{row['correct']}/4** deterministic correct, zero truncation/service/parse failures; prompt build {row['reader_prompt_build_s']:.2f}s, generation {row['reader_generation_s']:.2f}s.\n\nThis is text-only/adapted evidence: screenshots are omitted and official native/Judge quality remains pending. Earlier order/input-limit diagnostic failures are retained but excluded. Configuration: {row['configuration']}.\n")
if __name__=='__main__': main()
